using Google.Protobuf;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Tdl.Ir.V1;
using Tdl.Plugin;
using Tdl.Plugin.V1;
using static Microsoft.CodeAnalysis.CSharp.SyntaxFactory;
using Diagnostic = Tdl.Plugin.V1.Diagnostic;
using PluginFile = Tdl.Plugin.V1.File;

namespace Tdl.Gen.CSharp;

/// <summary>One request's generation.</summary>
sealed partial class Generator(Session s)
{
	/// <summary>
	/// Starts every file. &lt;auto-generated&gt; turns the nullable context off,
	/// so #nullable follows it. The pragma silences use of an obsolete member
	/// inside the file, since generated equality reads deprecated fields, and
	/// an obsolete required member, which C# otherwise refuses.
	/// </summary>
	const string Header = """
		// <auto-generated>
		// Code generated by tdl. DO NOT EDIT.
		// </auto-generated>
		#nullable enable
		#pragma warning disable CS0612, CS0618, CS9042

		""";

	/// <summary>The class each namespace declares once, comparing collections and bytes by their contents.</summary>
	const string EqualityType = "TdlEquality";

	// ns is the generated namespace.
	string ns = "";

	// names maps each declaration that declares a type to its C# name, and
	// owners each C# name to the declaration taking it.
	readonly Dictionary<Decl, string> names = new(ReferenceEqualityComparer.Instance);
	readonly Dictionary<string, string> owners = [];

	// attributes are the target block's attributes, which every declaration
	// carries.
	List<string> attributes = [];

	/// <summary>One declaration's output, and whether it reads the namespace's TdlEquality.</summary>
	sealed record Piece(string Name, string Text, bool Equality);

	public Response Generate()
	{
		try
		{
			ns = Namespace();
		}
		catch (ProblemException e)
		{
			s.Warn(e.Problem);
			return s.Response([]);
		}
		s.Externs = true;
		PlanForeign();
		attributes = AttributesOf(BlockDirectives());

		var own = s.Own();
		var skipped = new HashSet<Decl>(ReferenceEqualityComparer.Instance);
		foreach (var d in own)
		{
			try
			{
				Claim(d);
			}
			catch (ProblemException e)
			{
				s.Warn(e.Problem);
				skipped.Add(d);
			}
		}

		var output = new Dictionary<Decl, Piece>(ReferenceEqualityComparer.Instance);
		// Each declaration's warnings are held until the cascade decides
		// whether it is emitted.
		var held = new Dictionary<Decl, List<Diagnostic>>(ReferenceEqualityComparer.Instance);
		foreach (var d in own)
		{
			if (skipped.Contains(d))
			{
				continue;
			}
			var mark = s.Diagnostics.Count;
			Piece? p;
			try
			{
				p = Declare(d);
			}
			catch (ProblemException e)
			{
				s.Diagnostics.RemoveRange(mark, s.Diagnostics.Count - mark);
				s.Warn(e.Problem);
				skipped.Add(d);
				continue;
			}
			held[d] = s.Diagnostics[mark..];
			s.Diagnostics.RemoveRange(mark, s.Diagnostics.Count - mark);
			if (p is not null)
			{
				output[d] = p;
			}
		}
		s.Cascade(own, skipped);

		var emitted = new List<Piece>();
		foreach (var d in own)
		{
			if (output.TryGetValue(d, out var p) && !skipped.Contains(d))
			{
				s.Diagnostics.AddRange(held[d]);
				emitted.Add(p);
			}
		}
		if (emitted.Count == 0)
		{
			return s.Response([]);
		}
		if (emitted.Any(p => p.Equality))
		{
			emitted.Add(new Piece(EqualityType, EqualitySource.Text, false));
		}

		if (s.Block("file") is { } file)
		{
			var all = Start() + string.Concat(emitted.Select(p => "\n" + p.Text));
			return s.Response([new PluginFile { Path = file.Args[0].Text, Content = ByteString.CopyFromUtf8(all) }]);
		}
		return s.Response(emitted.Select(p => new PluginFile
		{
			Path = p.Name.TrimStart('@') + ".g.cs",
			Content = ByteString.CopyFromUtf8(Start() + "\n" + p.Text),
		}));
	}

	// Start is what every file begins with.
	string Start() => Header + $"\nnamespace {ns};\n";

	static ProblemException Unsupported(Position? pos, string message, string code = "") =>
		new(new Plugin.Unsupported(message, pos, code));

	// Claim records the C# name a declaration takes, before any is rendered,
	// so a reference to one declared later is spelled the same.
	void Claim(Decl d)
	{
		if (foreign.ContainsKey(d) || d.Structure is null && d.Enumeration is null && d.Newtype is null)
		{
			return;
		}
		var pos = d.Meta?.Position;
		var name = d.Meta?.Name;
		var typ = TypeName(d);
		if (Bare(typ) == EqualityType)
		{
			throw Unsupported(pos, $"{name} would be named {typ} in C#, which the generated equality class takes; a name directive resolves it");
		}
		if (owners.TryGetValue(typ, out var other))
		{
			throw Unsupported(pos, $"{name} would be named {typ} in C#, and {other} already is; a name directive on either resolves it");
		}
		names[d] = typ;
		owners[typ] = name ?? "";
	}

	// Declare renders one declaration, or null for one that declares nothing.
	Piece? Declare(Decl d)
	{
		var pos = d.Meta?.Position;
		var name = d.Meta?.Name;

		if (foreign.ContainsKey(d))
		{
			// Another assembly declares it.
			return null;
		}
		if (d.Class is not null)
		{
			throw Unsupported(pos, $"{name} is a class, and classes are not generated yet", LossCodes.Class);
		}
		if (d.Structure is null && d.Enumeration is null && d.Newtype is null)
		{
			// A primitive, an alias, and a unit declare nothing: an alias is
			// expanded where it is used, and C# has no units.
			return null;
		}
		if (Session.Params(d).Count > 0)
		{
			throw Unsupported(pos, $"{name} is parameterized, and generics are not generated yet", LossCodes.Generic);
		}

		var typ = names[d];
		var attrs = attributes.Concat(AttributesOf(d.Directives)).ToList();
		var key = s.Find(d.Directives, "key");
		if (key is not null && d.Structure is null)
		{
			s.Lossy(LossCodes.Key, key.Position, $"{name} has a key, and only an entity is identified by one");
			key = null;
		}

		var (decl, after, equality) =
			d.Newtype is not null ? Newtype(d, typ) :
			d.Structure is not null ? Record(name ?? "", typ, null, Session.Fields(d), null, d, key) :
			s.View(d)?.Fielded == true ? Union(d, typ) :
			(Enum(d, typ), null, false);

		s.WarnConstraints(d);
		decl = Decorate(decl, d.Meta, attrs);
		return new Piece(typ, Syntax.Text(after is null ? [decl] : [decl, after]), equality);
	}

	// Decorate puts a node's documentation, its Obsolete attribute, and the
	// attributes given on it.
	static T Decorate<T>(T node, Meta? m, IEnumerable<string> attrs) where T : MemberDeclarationSyntax
	{
		var lists = new List<AttributeListSyntax>();
		if (Session.Deprecated(m, out var reason))
		{
			lists.Add(Syntax.Attribute("global::System.Obsolete", reason == "" ? null : Syntax.String(reason)));
		}
		lists.AddRange(attrs.Select(a => Syntax.Attribute(a)));
		var decorated = (T)node.WithAttributeLists(List(lists.Concat(node.AttributeLists)));
		var doc = Syntax.Doc(Session.Doc(m));
		return doc.Count == 0 ? decorated : decorated.WithLeadingTrivia(doc);
	}

	// Newtype renders a newtype as a readonly record struct holding its base.
	(MemberDeclarationSyntax, MemberDeclarationSyntax?, bool) Newtype(Decl d, string typ)
	{
		if (Bare(typ) == "Value")
		{
			throw Unsupported(d.Meta?.Position,
				$"{d.Meta?.Name} would be named Value in C#, which its own property takes; a name directive resolves it");
		}
		var b = Type(d.Newtype.Base, null);
		var record = Syntax.RecordStruct(typ, [(b.Text, "Value")]);
		if (b.Cmp is null)
		{
			return (record.WithSemicolonToken(Token(SyntaxKind.SemicolonToken)), null, false);
		}
		var body = new List<MemberDeclarationSyntax>
		{
			Comparer("_value", b.Text, b.Cmp),
			MethodDeclaration(PredefinedType(Token(SyntaxKind.BoolKeyword)), "Equals")
				.WithModifiers(Syntax.Modifiers(SyntaxKind.PublicKeyword))
				.AddParameterListParameters(Parameter(Identifier("other")).WithType(ParseTypeName(typ)))
				.WithExpressionBody(ArrowExpressionClause(ParseExpression("_value.Equals(this.Value, other.Value)")))
				.WithSemicolonToken(Token(SyntaxKind.SemicolonToken)),
			Hash([("Value", "_value")]),
		};
		return (record.WithOpenBraceToken(Token(SyntaxKind.OpenBraceToken)).WithMembers(List(body)).WithCloseBraceToken(Token(SyntaxKind.CloseBraceToken)), null, true);
	}

	// Enum renders a fieldless enum as a C# enum.
	EnumDeclarationSyntax Enum(Decl d, string typ)
	{
		var seen = new HashSet<string>();
		var members = d.Enumeration.Variants
			.Select(v => Decorate(EnumMemberDeclaration(Syntax.Name(VariantName(d, typ, v, seen))), v.Meta, []))
			.ToList();
		return EnumDeclaration(Syntax.Name(typ))
			.WithModifiers(Syntax.Modifiers(SyntaxKind.PublicKeyword))
			.WithMembers(SeparatedList(members, members.Select(_ => Token(SyntaxKind.CommaToken))));
	}

	// Union renders an enum whose variants carry fields as an abstract
	// record closed by a private constructor, with a sealed nested record per
	// variant.
	(MemberDeclarationSyntax, MemberDeclarationSyntax?, bool) Union(Decl d, string typ)
	{
		var name = d.Meta?.Name ?? "";
		var variants = d.Enumeration.Variants;

		// A variant's name shadows a type of the same name inside the enum.
		var seen = new HashSet<string>();
		var vnames = variants.Select(v => VariantName(d, typ, v, seen)).ToList();
		var shadow = vnames.Select(Bare).ToHashSet();

		var equality = false;
		var members = new List<MemberDeclarationSyntax>
		{
			ConstructorDeclaration(Syntax.Name(typ)).WithModifiers(Syntax.Modifiers(SyntaxKind.PrivateKeyword)).WithBody(Block()),
		};
		for (var i = 0; i < variants.Count; i++)
		{
			var v = variants[i];
			var (record, _, eq) = Record($"{name}.{v.Meta?.Name}", vnames[i], typ, v.Fields, shadow, null, null);
			members.Add(Decorate(record, v.Meta, []));
			equality |= eq;
		}
		var union = Syntax.Record(Syntax.Modifiers(SyntaxKind.PublicKeyword, SyntaxKind.AbstractKeyword, SyntaxKind.PartialKeyword), typ, null, members);
		return (union, null, equality);
	}

	// Property is one field as a C# property. Init is the default it is
	// initialized to, or null.
	sealed record Property(string Name, CsType Type, bool Required, Field Field, ExpressionSyntax? Init);

	// Record renders a record: owner is its name as the model spells it, for
	// messages, and baseType the enum a variant's record derives from. It
	// reports whether the record writes its own equality. A key directive on
	// the entity d writes a Key method, and a key record after the record
	// when it names several fields.
	(MemberDeclarationSyntax, MemberDeclarationSyntax?, bool) Record(string owner, string typ, string? baseType, IList<Field> fields, ISet<string>? shadow, Decl? d, Directive? key)
	{
		var props = Properties(owner, typ, fields, shadow);
		MethodDeclarationSyntax? method = null;
		MemberDeclarationSyntax? after = null;
		if (key is not null)
		{
			try
			{
				(method, after) = Key(d!, typ, props, key);
			}
			catch (ProblemException e)
			{
				s.Warn(e.Problem);
			}
		}
		var modifiers = Syntax.Modifiers(SyntaxKind.PublicKeyword, SyntaxKind.SealedKeyword, SyntaxKind.PartialKeyword);
		if (props.Count == 0)
		{
			return (Syntax.Record(modifiers, typ, baseType, []), after, false);
		}

		var taken = props.Select(p => Bare(p.Name)).ToHashSet();
		var cmps = new List<FieldDeclarationSyntax>();
		var byProp = new Dictionary<string, string>();
		foreach (var p in props)
		{
			if (p.Type.Cmp is null)
			{
				continue;
			}
			var n = "_" + Tdl.DotNet.Net.LowerFirst(Bare(p.Name));
			while (!taken.Add(n))
			{
				n += "_";
			}
			cmps.Add(Comparer(n, p.Type.Text, p.Type.Cmp));
			byProp[p.Name] = n;
		}

		var members = new List<MemberDeclarationSyntax>(cmps);
		members.AddRange(props.Select(p => Decorate(Syntax.Property(p.Type.Text, p.Name, p.Required, p.Init), p.Field.Meta, [])));
		if (method is not null)
		{
			members.Add(method);
		}
		if (cmps.Count > 0)
		{
			ExpressionSyntax same = ParseExpression("other is not null");
			foreach (var p in props)
			{
				var cmp = byProp.GetValueOrDefault(p.Name) ?? CsType.DefaultComparer(p.Type.Text);
				same = BinaryExpression(SyntaxKind.LogicalAndExpression, same, ParseExpression($"{cmp}.Equals(this.{p.Name}, other.{p.Name})"));
			}
			members.Add(MethodDeclaration(PredefinedType(Token(SyntaxKind.BoolKeyword)), "Equals")
				.WithModifiers(Syntax.Modifiers(SyntaxKind.PublicKeyword))
				.AddParameterListParameters(Parameter(Identifier("other")).WithType(ParseTypeName(typ + "?")))
				.WithExpressionBody(ArrowExpressionClause(BinaryExpression(SyntaxKind.LogicalOrExpression, ParseExpression("object.ReferenceEquals(this, other)"), same)))
				.WithSemicolonToken(Token(SyntaxKind.SemicolonToken)));
			members.Add(Hash(props.Select(p => (p.Name, byProp.GetValueOrDefault(p.Name)))));
		}
		return (Syntax.Record(modifiers, typ, baseType, members), after, cmps.Count > 0);
	}

	// Properties maps fields to properties, refusing the names C# would.
	List<Property> Properties(string owner, string typ, IList<Field> fields, ISet<string>? shadow)
	{
		var props = new List<Property>();
		var seen = new Dictionary<string, string>();
		foreach (var f in fields)
		{
			var pos = f.Meta?.Position;
			var fname = f.Meta?.Name ?? "";
			if (!MemberName(FieldName(f), out var n, out var problem))
			{
				throw Unsupported(pos, $"{owner}.{fname} {problem}");
			}
			var bare = Bare(n);
			if (bare == Bare(typ))
			{
				throw Unsupported(pos, $"{owner}.{fname} would be the property {n} in C#, which a member of {typ} cannot be named; a name directive resolves it");
			}
			if (ReservedMembers.Contains(bare))
			{
				throw Unsupported(pos, $"{owner}.{fname} would be the property {n} in C#, which every record declares; a name directive resolves it");
			}
			if (seen.TryGetValue(bare, out var other))
			{
				throw Unsupported(pos, $"{owner}.{fname} and {other} would both be the property {n} in C#; a name directive on either resolves it");
			}
			seen[bare] = fname;

			var (t, required) = FieldType(f, shadow);
			ExpressionSyntax? init = null;
			if (f.DefaultValue is { } lit)
			{
				try
				{
					init = ParseExpression(DefaultValue(f.Type, lit, shadow));
					required = false;
				}
				catch (ProblemException e)
				{
					s.Warn(e.Problem);
				}
			}
			props.Add(new Property(n, t, required, f, init));
		}
		return props;
	}

	// Comparer is a static field holding the comparer a property is compared by.
	static FieldDeclarationSyntax Comparer(string name, string type, string expr) =>
		FieldDeclaration(VariableDeclaration(ParseTypeName($"global::System.Collections.Generic.IEqualityComparer<{type}>"))
				.AddVariables(VariableDeclarator(name).WithInitializer(EqualsValueClause(ParseExpression(expr)))))
			.WithModifiers(Syntax.Modifiers(SyntaxKind.PrivateKeyword, SyntaxKind.StaticKeyword, SyntaxKind.ReadOnlyKeyword));

	// Hash is GetHashCode over every property, through its comparer when it
	// has one.
	static MethodDeclarationSyntax Hash(IEnumerable<(string Name, string? Comparer)> props) =>
		MethodDeclaration(PredefinedType(Token(SyntaxKind.IntKeyword)), "GetHashCode")
			.WithModifiers(Syntax.Modifiers(SyntaxKind.PublicKeyword, SyntaxKind.OverrideKeyword))
			.WithBody(Block(List(
				[
					ParseStatement("var hash = new global::System.HashCode();"),
					.. props.Select(p => ParseStatement(p.Comparer is null ? $"hash.Add(this.{p.Name});" : $"hash.Add(this.{p.Name}, {p.Comparer});")),
					ParseStatement("return hash.ToHashCode();"),
				])));
}
